<?php require_once 'includes/auth.php'; require_login(); if($_SESSION['user']['role']!=='student'){header('Location: admin.php');exit;} $errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){ $cat=trim($_POST['category']??'');$loc=trim($_POST['location']??'');$desc=trim($_POST['description']??'');$image=null; if(!$cat)$errors[]='Choose a category.';if(!$loc)$errors[]='Enter the location.';if(strlen($desc)<10)$errors[]='Please describe the problem in at least 10 characters.'; if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['image'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($f['size']>5*1024*1024||!isset($allowed[$mime]))$errors[]='Image must be JPG, PNG or WEBP and under 5MB.';else{$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$name))$image=$name;else $errors[]='Could not upload image.';}} if(!$errors){$st=$pdo->prepare('INSERT INTO complaints(user_id,category,location,description,image) VALUES(?,?,?,?,?)');$st->execute([$_SESSION['user']['id'],$cat,$loc,$desc,$image]);header('Location: complaint.php?id='.$pdo->lastInsertId().'&created=1');exit;}} $page_title='Report an Issue';include 'includes/header.php'; ?>
<div class="page-head compact"><div><div class="eyebrow">NEW COMPLAINT</div><h1>Report a campus issue</h1><p class="muted">Give the campus team enough detail to act quickly.</p></div></div>
<?php if($errors): ?><div class="alert error"><b>Please check the form:</b><ul><?php foreach($errors as $x): ?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif; ?><form class="form-card" method="post" enctype="multipart/form-data"><div class="form-section"><div class="form-section-title"><span>01</span><div><b>What needs attention?</b><small>Select the closest category.</small></div></div><div class="category-grid"><?php foreach(['Electrical'=>'⚡','Plumbing'=>'◉','Internet'=>'⌁','Furniture'=>'▣','Cleaning'=>'✦','Other'=>'＋'] as $name=>$icon): ?><label class="category-option"><input type="radio" name="category" value="<?=e($name)?>" <?=($_POST['category']??'')===$name?'checked':''?> required><span><i><?=$icon?></i><b><?=e($name)?></b></span></label><?php endforeach;?></div></div><div class="form-section"><div class="form-section-title"><span>02</span><div><b>Where is it?</b><small>Be as specific as possible.</small></div></div><label>Location<input name="location" value="<?=e($_POST['location']??'')?>" required placeholder="e.g. Block B, Room 204"></label></div><div class="form-section"><div class="form-section-title"><span>03</span><div><b>Tell us what happened</b><small>A clear description helps us resolve it faster.</small></div></div><label>Description<textarea name="description" rows="6" required minlength="10" placeholder="Describe the issue, what you noticed, and anything else that may help..."><?=e($_POST['description']??'')?></textarea><div class="char-count" data-for="description">0 / 1000</div></label></div><div class="form-section"><div class="form-section-title"><span>04</span><div><b>Add a photo <small>(optional)</small></b><small>JPG, PNG or WEBP · max 5MB</small></div></div><label class="upload-box" for="image"><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/webp"><span class="upload-icon">↑</span><b>Drop an image here or browse</b><small id="fileName">No file selected</small></label></div><div class="form-actions"><a class="btn btn-ghost" href="dashboard.php">Cancel</a><button class="btn btn-primary" type="submit">Submit complaint <span>→</span></button></div></form><?php include 'includes/footer.php'; ?>
